function auditIsGwenModifier(effect: ActiveEffect): boolean {
  return effect.source.heroName === "Gwen" && ["EagleVision/1", "AirDominance/2"].includes(effect.source.effectId ?? effect.intent.id);
}

function auditCalculateDamageJob(job: DamageJob, fighters: Record<SideId, ResolvedFighter>, options: DamageJobOptions, runtime: Runtime) {
  const snapshot: ActiveEffect[] | undefined = (runtime as any).auditGwenNormalSnapshot;
  if (!snapshot) return calculateDamageJob(job, fighters, options);
  const borrowed = new Set(snapshot);
  const liveEffectsByGroup = options.effectIndex.liveEffectsByGroup.map((live, ordinal) => [
    ...live.filter(effect => !auditIsGwenModifier(effect)),
    ...snapshot.filter(effect => effect.effectGroup?.ordinal === ordinal)
  ]);
  const result = calculateDamageJob(job, fighters, {...options, effectIndex: {...options.effectIndex, liveEffectsByGroup}});
  for (const list of [runtime.usedEffects, runtime.primaryUsedEffects]) {
    for (let index = list.length - 1; index >= 0; index--) {
      if (borrowed.has(list[index])) list.splice(index, 1);
    }
  }
  return result;
}

